def fib4(n: int):
    if n < 0:
        raise ValueError("Invalid input")

    fib_cache = [0, 0, 2] + [0] * (n - 3)

    for i in range(4, n + 1):
        fib_cache[i] = fib_cache[i-1] + fib_cache[i-2] + fib_cache[i-3] + fib_cache[i-4]

    return fib_cache[n]
